const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '..', '.env') });

const {
  PORT = 5000,
  NODE_ENV = 'development',
  JWT_SECRET = 'your-secret-key-change-in-production',
  JWT_EXPIRES_IN = '7d',
  BCRYPT_ROUNDS = 10,
  FRONTEND_URL = 'http://localhost:5173',
  UPLOAD_MAX_SIZE = 5 * 1024 * 1024, // 5MB
  UPLOAD_ALLOWED_TYPES = 'image/jpeg,image/png,image/gif,image/webp'
} = process.env;

module.exports = {
  PORT: parseInt(PORT, 10),
  NODE_ENV,
  JWT_SECRET,
  JWT_EXPIRES_IN,
  BCRYPT_ROUNDS: parseInt(BCRYPT_ROUNDS, 10),
  FRONTEND_URL,
  UPLOAD_MAX_SIZE: parseInt(UPLOAD_MAX_SIZE, 10),
  UPLOAD_ALLOWED_TYPES: UPLOAD_ALLOWED_TYPES.split(',').map(type => type.trim())
};

import { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import './styles/App.css';

// Layout components
import Header from './components/layout/Header';
import Footer from './components/layout/Footer';
import Sidebar from './components/layout/Sidebar';

// Page components
import HomePage from './pages/HomePage';
import BlogListPage from './pages/BlogListPage';
import BlogDetailPage from './pages/BlogDetailPage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import ProfilePage from './pages/ProfilePage';
import DashboardPage from './pages/DashboardPage';
import CreateBlogPage from './pages/CreateBlogPage';
import EditBlogPage from './pages/EditBlogPage';
import CategoriesPage from './pages/CategoriesPage';
import TagsPage from './pages/TagsPage';
import SearchPage from './pages/SearchPage';
import NotFoundPage from './pages/NotFoundPage';

// Context providers
import { AuthProvider } from './contexts/AuthContext';
import { BlogProvider } from './contexts/BlogContext';

function App() {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Close sidebar when route changes (mobile)
  useEffect(() => {
    const handleRouteChange = () => {
      if (window.innerWidth < 768) {
        setIsSidebarOpen(false);
      }
    };
    // This would be tied to router events in a real implementation
  }, []);

  return (
    <AuthProvider>
      <BlogProvider>
        <Router>
          <div className="app">
            <Header onMenuClick={() => setIsSidebarOpen(!isSidebarOpen)} />

            <div className="main-container">
              <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />

              <main className="main-content">
                <Routes>
                  <Route path="/" element={<HomePage />} />
                  <Route path="/blogs" element={<BlogListPage />} />
                  <Route path="/blogs/:id" element={<BlogDetailPage />} />
                  <Route path="/categories" element={<CategoriesPage />} />
                  <Route path="/categories/:id" element={<BlogListPage />} />
                  <Route path="/tags" element={<TagsPage />} />
                  <Route path="/tags/:id" element={<BlogListPage />} />
                  <Route path="/search" element={<SearchPage />} />
                  <Route path="/login" element={<LoginPage />} />
                  <Route path="/register" element={<RegisterPage />} />
                  <Route path="/profile" element={<ProfilePage />} />
                  <Route path="/dashboard" element={<DashboardPage />} />
                  <Route path="/blogs/new" element={<CreateBlogPage />} />
                  <Route path="/blogs/:id/edit" element={<EditBlogPage />} />
                  <Route path="/404" element={<NotFoundPage />} />
                  <Route path="*" element={<Navigate to="/404" replace />} />
                </Routes>
              </main>
            </div>

            <Footer />
          </div>
        </Router>
      </BlogProvider>
    </AuthProvider>
  );
}

export default App;

