#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const sqlite3 = require('sqlite3').verbose();

const schemaPath = path.join(__dirname, '..', 'database', 'schema.sql');
const dbPath = process.env.DB_PATH || path.join(__dirname, '..', 'database.sqlite');

console.log('Initializing SQLite database...');
console.log('Database path:', dbPath);
console.log('Schema path:', schemaPath);

// Ensure the schema file exists
if (!fs.existsSync(schemaPath)) {
    console.error('Schema file not found:', schemaPath);
    process.exit(1);
}

// Read schema SQL
const schemaSql = fs.readFileSync(schemaPath, 'utf8');

// Connect to database (creates if not exists)
const db = new sqlite3.Database(dbPath, (err) => {
    if (err) {
        console.error('Error opening database:', err.message);
        process.exit(1);
    }
    console.log('Connected to SQLite database.');
});

// Enable foreign keys
db.run('PRAGMA foreign_keys = ON');

// Split SQL by semicolons (simple approach)
const statements = schemaSql
    .split(';')
    .map(stmt => stmt.trim())
    .filter(stmt => stmt.length > 0);

let completed = 0;
const total = statements.length;

function executeStatement(index) {
    if (index >= statements.length) {
        console.log(`All ${total} SQL statements executed successfully.`);
        db.close((err) => {
            if (err) {
                console.error('Error closing database:', err.message);
            } else {
                console.log('Database connection closed.');
            }
            process.exit(0);
        });
        return;
    }

    const stmt = statements[index];
    db.run(stmt, (err) => {
        if (err) {
            console.error(`Error executing statement ${index + 1}:`, err.message);
            console.error('SQL:', stmt);
            db.close();
            process.exit(1);
        } else {
            completed++;
            console.log(`[${completed}/${total}] Statement ${index + 1} executed.`);
            executeStatement(index + 1);
        }
    });
}

console.log(`Found ${total} SQL statements to execute.`);
executeStatement(0);

